var a=22;var i=[{id:`cooking-022-01`,theoryId:22,type:`single_choice`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Which is an approved home method to thaw frozen chicken?`,ua:`Який спосіб розморожування курятини є безпечним у побутових рекомендаціях?`},explanation:{en:`Refrigerator thawing keeps the food cold while ice melts.`,ua:`Розморожування в холодильнику зберігає продукт холодним під час танення льоду.`},options:[{id:`a`,text:{en:`In a refrigerator`,ua:`У холодильнику`}},{id:`b`,text:{en:`On the countertop overnight`,ua:`На столі протягом ночі`}},{id:`c`,text:{en:`In warm water for many hours`,ua:`У теплій воді на багато годин`}},{id:`d`,text:{en:`On a sunny windowsill`,ua:`На сонячному підвіконні`}}],answer:{optionIds:[`a`]}},{id:`cooking-022-02`,theoryId:22,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which thawing methods are recognized by US home-safety guidance?`,ua:`Які способи розморожування визнають домашні рекомендації США?`},explanation:{en:`The refrigerator, cold water, and microwave are recognized options, each with handling requirements.`,ua:`Холодильник, холодна вода та мікрохвильовка — допустимі способи з відповідними правилами.`},options:[{id:`a`,text:{en:`Refrigerator thawing`,ua:`Розморожування в холодильнику`}},{id:`b`,text:{en:`Cold-water thawing with suitable precautions`,ua:`Розморожування в холодній воді з належними запобіжними заходами`}},{id:`c`,text:{en:`Microwave thawing followed by immediate cooking`,ua:`Розморожування в мікрохвильовці з негайним приготуванням`}},{id:`d`,text:{en:`Leaving meat on a warm counter all day`,ua:`Залишити м’ясо на теплому столі на весь день`}}],answer:{optionIds:[`a`,`b`,`c`]}},{id:`cooking-022-03`,theoryId:22,type:`sequence`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Arrange cold-water thawing for packaged meat under US guidance.`,ua:`Упорядкуйте розморожування запакованого м’яса у холодній воді за рекомендаціями США.`},explanation:{en:`Leak-proof packaging and cold-water changes help keep the process controlled.`,ua:`Герметичність пакування й заміна холодної води допомагають контролювати процес.`},steps:[{id:`s2`,text:{en:`Submerge in cold water`,ua:`Занурити в холодну воду`}},{id:`s4`,text:{en:`Cook promptly after thawing`,ua:`Оперативно приготувати після розморожування`}},{id:`s1`,text:{en:`Check that packaging is leak-proof`,ua:`Переконатися, що пакування герметичне`}},{id:`s3`,text:{en:`Replace water about every 30 minutes`,ua:`Замінювати воду приблизно кожні 30 хвилин`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}},{id:`cooking-022-04`,theoryId:22,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Meat thawed in the microwave can always be returned uncooked to the refrigerator for several days.`,ua:`М’ясо, розморожене в мікрохвильовці, завжди можна покласти сирим у холодильник ще на кілька днів.`},explanation:{en:`Microwave and cold-water thawing call for prompt cooking under US home guidance.`,ua:`За американськими домашніми рекомендаціями після розморожування в мікрохвильовці чи холодній воді продукт потрібно швидко приготувати.`},answer:{value:!1}},{id:`cooking-022-05`,theoryId:22,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which thawing practice is unsafe?`,ua:`Яке розморожування є небезпечним?`},explanation:{en:`The exterior can enter unsafe temperatures while the interior remains frozen.`,ua:`Зовнішній шар може нагрітися до небезпечної температури, поки середина ще заморожена.`},options:[{id:`a`,text:{en:`Thaw in a refrigerator`,ua:`Розморожувати в холодильнику`}},{id:`b`,text:{en:`Use cold water with controlled changes`,ua:`Використовувати холодну воду зі своєчасною заміною`}},{id:`c`,text:{en:`Leave raw poultry on a warm counter overnight`,ua:`Лишати сиру птицю на теплому столі на ніч`}},{id:`d`,text:{en:`Cook immediately after microwave thawing`,ua:`Готувати одразу після розморожування в мікрохвильовці`}}],answer:{optionIds:[`c`]}},{id:`cooking-022-06`,theoryId:22,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`You need to cook frozen chicken now. What is a safe choice?`,ua:`Потрібно зараз приготувати заморожену курятину. Яке рішення безпечне?`},explanation:{en:`A microwave thaw is acceptable if the food is cooked immediately afterward.`,ua:`Мікрохвильове розморожування можливе, якщо одразу після нього продукт готують.`},options:[{id:`a`,text:{en:`Use a suitable microwave defrost cycle and cook immediately`,ua:`Скористатися відповідним режимом розморожування в мікрохвильовці та одразу приготувати`}},{id:`b`,text:{en:`Leave at room temperature until tomorrow`,ua:`Залишити до завтра за кімнатної температури`}},{id:`c`,text:{en:`Put it on a radiator`,ua:`Покласти на батарею`}},{id:`d`,text:{en:`Immerse it in hot water for hours`,ua:`Тримати годинами в гарячій воді`}}],answer:{optionIds:[`a`]}}];var n={theoryId:22,exercises:i};export{n as default,i as exercises,a as theoryId};